```go
package main
import (
"bytes"
"fmt"
"runtime"
"sync/atomic"
)
func main() {
sem := make(chan struct{}, runtime.NumCPU())
array := bytes.Repeat([]byte("a"), 1000_0000)
var c int64
for _, b := range array {
b := b
sem <- struct{}{}
go func() {
defer func() {
<-sem
}()
_ = b
if n := atomic.AddInt64(&c, 1); n%10000 == 0 {
fmt.Printf("%d\n", n)
}
}()
}
for i := 0; i < cap(sem); i++ {
sem <- struct{}{}
}
}
```
给你看一个并发模式，1 千万个任务，最多有 runtime.NumCPU() 个同时跑，而不是像你那样，不停开 1 千万个 goroutine

